def sigs(G):
    d=[x.bit_count() for x in G]
    return [(
        d[v],
        tuple(sorted(d[w] for w in range(len(G)) if G[v]>>w&1)),
        tuple(sorted((G[v]&G[w]).bit_count() for w in range(len(G)) if v!=w))
    ) for v in range(len(G))]

def iso(G,H):
    n=len(G)
    a,b=sigs(G),sigs(H)
    if sorted(a)!=sorted(b):
        return False
    dst=[[w for w in range(n) if a[v]==b[w]] for v in range(n)]
    order=sorted(range(n),key=lambda v:len(dst[v]))
    p=[None]*n
    def go(i,used):
        if i==n:return True
        v=order[i]
        for w in dst[v]:
            if used>>w&1:continue
            if any((G[v]>>u&1)!=(H[w]>>p[u]&1) for u in order[:i]):continue
            p[v]=w
            if go(i+1,used|(1<<w)):return True
        p[v]=None
        return False
    return go(0,0)

def ind(G,S):
    v=S
    while v:
        x=v&-v;v^=x
        if G[x.bit_length()-1]&v:
            return False
    return True

def alpha(G):
    return max(S.bit_count() for S in range(1<<len(G)) if ind(G,S))

def comps(G,S):
    out=[]
    while S:
        cur=S&-S
        Q=cur
        while Q:
            v=Q&-Q
            Q^=v
            add=G[v.bit_length()-1]&S&~cur
            cur|=add;Q|=add
        out.append(cur);S^=cur
    return out

def fc(G,S):
    @lru_cache(None)
    def perfect(Z):
        if not Z:return True
        x=Z&-Z
        return any(perfect(Z^x^(1<<j)) for j in range(len(G))
                   if (G[x.bit_length()-1]&Z)>>j&1)
    return all(perfect(S^(1<<j)) for j in range(len(G)) if S>>j&1)

def barrier(G):
    all_=(1<<len(G))-1
    def score(t):
        sizes=[c.bit_count() for c in comps(G,all_^t)]
        return sum(z%2 for z in sizes)-t.bit_count(),t.bit_count()
    t=max(range(all_+1),key=score)
    C=comps(G,all_^t)
    assert all(m.bit_count()%2 for m in C)
    assert all(fc(G,m) for m in C)
    return (t.bit_count(),tuple(sorted(z.bit_count() for z in C)))

def census(n,cap):
    Gs=[()]
    for j in range(n):
        gs=defaultdict(list)
        for G in Gs:
            Gind=[S for S in range(1<<j) if ind(G,S)]
            oldind=[S for S in Gind if S.bit_count()==cap]
            for nb in Gind:
                if any(nb&s==0 for s in oldind):
                    continue
                H=tuple(g+(1<<j if nb>>i&1 else 0) for i,g in enumerate(G))+(nb,)
                k=tuple(sorted(sigs(H)))
                if not any(iso(H,C) for C in gs[k]):gs[k].append(H)
        Gs=[H for row in gs.values() for H in row]
    return Gs

def main():
    for n,k,sizes in [(7,3,(9,9)),(9,4,(290,170))]:
        Gs=census(n,k)
        assert len(Gs)==sizes[0]
        F=[G for G in Gs if n==7 or fc(G,(1<<n)-1)]
        V=DB[1 if n==7 else 2]
        assert len(F)==len(V)==sizes[1]
        for G in V:
            assert all(0<=g<1<<n and not(g>>i&1) for i,g in enumerate(G))
            assert all((G[i]>>j&1)==(G[j]>>i&1) for i,j in combinations(range(n),2))
            assert all(ind(G,g) for g in G) and alpha(G)<=k
        hits=[sum(iso(G,H) for H in F) for G in V]
        assert all(x==1 for x in hits)
        assert not any(iso(G,H) for G,H in combinations(V,2))
        if n==9:
            skip=Counter(barrier(G) for G in Gs if G not in F)
            assert sum(skip.values())==120
            assert set(skip)=={(1,(1,7)),(2,(1,1,5))}
            print('non-factor-critical barrier cases',skip)
        print('independent census PASS',n,len(Gs),len(F))


if __name__=='__main__':
    main()
